/**
 * Turn free text into a URL slug: lower case, words joined by single hyphens,
 * no leading or trailing hyphen. Accented Latin letters lose their accents.
 */
export function slugify(text) {
  return String(text)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

